window.VeilGardeData.files["root"] = {"group":"root","files":[{"path":".gitignore","status":"added","lang":"text","hunks":[[1,0,1,45]],"header":null,"marks":[],"first":1600,"scopes":[],"old":"","new":"# SwiftPM / Xcode\n.build/\n.swiftpm/\nxcuserdata/\n*.xcodeproj\n*.dSYM\nDerivedData/\nPackage.resolved.orig\n\n# Editors and local tooling (CLAUDE.md is a local working file, never committed)\n.vscode/\n.claude/\nCLAUDE.md\n.DS_Store\n__pycache__/\n\n# Weights and Metal libraries stay out of the repo (they go to the work area or an override folder)\n*.safetensors\n*.metallib\n/WeightOverride/\n# ...except the small files the package ships: the test fixtures and the router's prompts\n!/Tests/**/Fixtures/**/*.safetensors\n!/Sources/VeilGardeFlywheel/Resources/clip_prompts_v1.safetensors\n\n# The playground's scratch work area (Playground/run.sh)\n/Playground/.work/\n/Playground/.build/\n/Playground/.swiftpm/\n\n# Local only: everything in docs/ but the site (docs/site is the documentation), and the maintainer's own scripts,\n# which need the research environment, Garde or this Mac's layout\n/docs/*\n!/docs/site/\n/scripts/fixtures/\n/scripts/lib.sh\n/scripts/parity-garde.sh\n/scripts/test.sh\n/scripts/weights.sh\n\n# The site regenerates these: exports and check screenshots\n/docs/site/export/\n/docs/site/.check/\n# The ask orb's key, copied from this Mac's ~/.rao by docs/site/src/askkey.py: never committed\n/docs/site/local/\n/Docs/site/local/\n"},{"path":"Package.swift","status":"added","lang":"swift","hunks":[[1,0,1,184]],"header":null,"marks":[],"first":1600,"scopes":[],"old":"","new":"// swift-tools-version: 6.4\n// SPDX-License-Identifier: GPL-3.0-only\n// VeilGarde — an AI-generated-image detector and a crop-robust watermark, as one package anyone\n// can train and run: a stack of independent members (the camera head over DINOv2 and the capture\n// signature, the screenshot head, the specialist heads, the semantic tiles) and the revisions that\n// read them, the trainers and the flywheel that grow them, and a watermark read off a\n// perspective-warp residual.\n//\n// Four products: VeilGarde (everything), VeilGardeInference (the detector alone), VeilWatermark\n// (the signature alone) and the `veilgarde` executable. Eight targets, in layers:\n//   VeilGardeCore       the domain, Foundation + Crypto only, Swift 6 strict: Support/ (JSON,\n//                       hashing, failures, the work area, safetensors, seeded splits), Features/\n//                       (capture 9, the screenshot gate, the camera row), Boost/ (GBDTModel: the\n//                       XGBoost JSON codec and evaluator), Heads/ (linear heads, the stack\n//                       combiner), Bundle/ (artifacts, the manifest, SHA-256 binding), Result/\n//                       (members' outputs, revisions' records, the schema-v1 JSON, the verdict\n//                       law, route batches), Store/ (the features-only store, its migration)\n//   VeilGardeLens       the extractors, in the order a pixel travels: Image/, Capture/,\n//                       Semantic/ (DINOv2, CLIP vision), Scoring/\n//                                                          (MLX through Frigate, Swift 5 mode)\n//   VeilGardeInference  the detector as one pipeline, Decode → Shared Signals → Stack → Revisions\n//                       → Result: Config/, Route/ (the signals, the Detector), Stack/ (the\n//                       pipeline, the members), Revisions/, Bundle/ (the shipped artifacts)\n//                                                                     (Swift 5 mode, resources)\n//   VeilGardeTraining   the trainers: Data/, Extract/, Boost/ (a native GBDT), Linear/, Camera/,\n//                       Heads/, Combiner/, Backbone/ (DINOv2 and CLIP imports), Recipe/ (the\n//                       trainable members), Engine/, Artifacts/                  (Swift 5 mode)\n//   VeilGardeFlywheel   the regime that grows the stack: Area/, Store/, Acquire/, Ingest/,\n//                       Candidates/, Battery/, Promote/                          (Swift 5 mode)\n//   VeilWatermark       the crop-robust signature on the warp residual: Residual/ (the warp\n//                       round trip and the fragility rate), Signature/, Sections/, Match/,\n//                       Acceptance/                            (MLX through Frigate, Swift 5 mode)\n//   VeilGarde           the umbrella, and the doctor that checks every layer     (Swift 5 mode)\n//   VeilGardeCLI        the `veilgarde` executable                               (Swift 5 mode)\n//\n// Invariants PackageLayeringTests holds: exactly these four products; MLX only through Frigate\n// (no mlx-swift URL here, and every MLX or Frigate import sits in a target that lists that\n// product); Core imports Foundation and Crypto only; Training never imports Inference or the\n// Flywheel; VeilWatermark imports Core, Lens and, for its residual, MLX and MLXAccelerate; nothing\n// under Sources/ imports MLXLLM, MLXLMCommon, AppKit or UIKit; no type is named like a module;\n// every Swift file opens with a WHAT: header.\n//\n// Frigate, the family's vendored MLX stack, is taken by path, as every consumer in the family\n// takes it: VEILGARDE_FRIGATE_DIR, else ../Frigate, else ../../rao/repositories/Frigate (this\n// Mac's layout). MLX-facing targets use Swift 5 language mode because Frigate's MLX types are not\n// Sendable (Braid's choice).\n\nimport Foundation\nimport PackageDescription\n\nlet v5: [SwiftSetting] = [.swiftLanguageMode(.v5)]\n\n/// Frigate's checkout: the one the environment names, else the first sibling layout that holds one.\nlet frigate: String = {\n    let root = URL(fileURLWithPath: Context.packageDirectory)\n    var candidates: [String] = []\n    if let named = Context.environment[\"VEILGARDE_FRIGATE_DIR\"], !named.isEmpty { candidates.append(named) }\n    candidates += [\"../Frigate\", \"../../rao/repositories/Frigate\"]\n    for candidate in candidates {\n        let url = candidate.hasPrefix(\"/\") ? URL(fileURLWithPath: candidate) : root.appendingPathComponent(candidate)\n        if FileManager.default.fileExists(atPath: url.appendingPathComponent(\"Package.swift\").path) { return candidate }\n    }\n    return \"../Frigate\"\n}()\n\n/// Weights stay out of git. Copied into the Inference resources, the DINOv2 files ship inside the bundle;\n/// otherwise WeightLocator finds them in the work area or an override folder.\nlet optionalWeights: [Resource] = [\n    \"Resources/dinov2_small.safetensors\",\n    \"Resources/dinov2_small_xsmall.safetensors\",\n    \"Resources/dinov2_small_xxsmall.safetensors\",\n].filter {\n    FileManager.default.fileExists(atPath: Context.packageDirectory + \"/Sources/VeilGardeInference/\" + $0)\n}.map { .copy($0) }\n\nlet package = Package(\n    name: \"VeilGarde\",\n    platforms: [.macOS(\"26.0\")],\n    products: [\n        .library(name: \"VeilGarde\", targets: [\"VeilGarde\"]),\n        .library(name: \"VeilGardeInference\", targets: [\"VeilGardeInference\"]),\n        .library(name: \"VeilWatermark\", targets: [\"VeilWatermark\"]),\n        .executable(name: \"veilgarde\", targets: [\"VeilGardeCLI\"]),\n    ],\n    dependencies: [\n        .package(path: frigate),\n        .package(url: \"https://github.com/apple/swift-argument-parser\", from: \"1.3.0\"),\n        .package(url: \"https://github.com/apple/swift-crypto.git\", from: \"4.2.0\"),\n    ],\n    targets: [\n        .target(\n            name: \"VeilGardeCore\",\n            dependencies: [.product(name: \"Crypto\", package: \"swift-crypto\")]\n        ),\n        .target(\n            name: \"VeilGardeLens\",\n            dependencies: [\n                \"VeilGardeCore\",\n                .product(name: \"MLX\", package: \"Frigate\"),\n                .product(name: \"MLXNN\", package: \"Frigate\"),\n                .product(name: \"MLXFFT\", package: \"Frigate\"),\n                .product(name: \"MLXAccelerate\", package: \"Frigate\"),\n                // FrigateBoost's XGBoostTreeModel, the evaluator the fusion head is scored with.\n                .product(name: \"Frigate\", package: \"Frigate\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeInference\",\n            dependencies: [\"VeilGardeLens\"],\n            // The shipped bundle: the shipped artifacts, by name, bound by manifest.json. Weights are\n            // gitignored and resolved at run time (WeightLocator); copied into this folder they ship\n            // inside the bundle.\n            resources: [\n                .copy(\"Resources/manifest.json\"),\n                .copy(\"Resources/camera.xgb.json\"),\n                .copy(\"Resources/stack_combiner.json\"),\n                .copy(\"Resources/screenshot_dinov2_v1.10.json\"),\n                .copy(\"Resources/art_dinov2_v2.json\"),\n                .copy(\"Resources/blur_dinov2_v1.json\"),\n                .copy(\"Resources/human_dinov2_v4.json\"),\n                .copy(\"Resources/semtile_dinov2_v1.json\"),\n                .copy(\"Resources/preview_dinov2_v1.json\"),\n            ] + optionalWeights,\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeTraining\",\n            dependencies: [\n                \"VeilGardeLens\",\n                .product(name: \"MLX\", package: \"Frigate\"),\n                .product(name: \"MLXNN\", package: \"Frigate\"),\n                .product(name: \"FrigateHub\", package: \"Frigate\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeFlywheel\",\n            dependencies: [\"VeilGardeTraining\", \"VeilGardeInference\"],\n            // The battery's spec and ratchet floors, byte for byte (`flywheel init` copies them into\n            // the work area, where the battery reads them); the category router's prompt matrix;\n            // the collector jobs that fill each blind spot.\n            resources: [\n                .copy(\"Resources/battery_spec.json\"),\n                .copy(\"Resources/battery_baseline.json\"),\n                .copy(\"Resources/clip_prompts_v1.safetensors\"),\n                .copy(\"Resources/acquire_targets_v1.json\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilWatermark\",\n            dependencies: [\n                \"VeilGardeLens\",\n                // The warp residual it reads: Frigate's warp tap tables, bicubic gathers and Gaussian blur;\n                // the seams' rFFT for the 19 tile features its residual statistics summarise.\n                .product(name: \"MLX\", package: \"Frigate\"),\n                .product(name: \"MLXAccelerate\", package: \"Frigate\"),\n                .product(name: \"MLXFFT\", package: \"Frigate\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGarde\",\n            dependencies: [\"VeilGardeInference\", \"VeilGardeTraining\", \"VeilGardeFlywheel\", \"VeilWatermark\"],\n            swiftSettings: v5\n        ),\n        .executableTarget(\n            name: \"VeilGardeCLI\",\n            dependencies: [\n                \"VeilGarde\",\n                .product(name: \"ArgumentParser\", package: \"swift-argument-parser\"),\n            ],\n            swiftSettings: v5\n        ),\n        .testTarget(name: \"VeilGardeCoreTests\", dependencies: [\"VeilGardeCore\"], exclude: [\"Fixtures\"]),\n        .testTarget(name: \"VeilGardeLensTests\", dependencies: [\"VeilGardeLens\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeInferenceTests\", dependencies: [\"VeilGardeInference\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeTrainingTests\", dependencies: [\"VeilGardeTraining\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeFlywheelTests\", dependencies: [\"VeilGardeFlywheel\"], swiftSettings: v5),\n        .testTarget(name: \"VeilWatermarkTests\", dependencies: [\"VeilWatermark\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeCLITests\", dependencies: [\"VeilGardeCLI\"], swiftSettings: v5),\n    ]\n)\n"},{"path":"README.md","status":"added","lang":"markdown","hunks":[[1,0,1,146]],"header":null,"marks":[],"first":1600,"scopes":[],"old":"","new":"[![VeilGarde: one verdict, and a signature that survives a crop. An image's 16 by 16 tiles, coloured by how generated each reads and lit by its fragility, feed two lanes: above, the stack's members and the combined verdict, ending in a gold mark; below, sixteen warps and the signature's id, ending in a square.](README_Assets/hero.png)](README_Assets/hero.png)\n\n# VeilGarde\n\nVeilGarde is a detector for AI-generated images, with a crop-robust watermark, as one Swift package you can train and run on a Mac. [Veil](https://veil.rao.nyc) is the pipeline, [Veil8](https://github.com/riteshpakala/Veil8) the PPM, VeilGarde the detection and watermarking.\n\nIt runs in two lanes.\n\n**Detection** is five stages: Decode, Shared Signals, Stack, Revisions, Result. The **stack** is a flat list of independent members, each with its own score:\n\n- the **camera head**, reading what an image depicts, from a frozen DINOv2 embedding, and whether a camera captured its pixels, from the **capture signature** measured at native resolution;\n- the screenshot gate and its content head;\n- the capture signature itself;\n- **specialist heads** for art, blur, faces and previews;\n- the semantic tiles.\n\nThree **revisions** read them. A small non-negative **combiner** anchors on the camera head, or on the screenshot head when the gate fires, and pools the specialists' evidence; the frame seam and the preview tail act only on decisive evidence. The result lists every member's score. A **flywheel** trains and improves the members from a store of features, without ever storing an image. Inference and training are declared the same way, so a new member is one file and one line on each side.\n\n**The watermark.** Every 32×32 tile of an image is perspective-warped through 16 fixed homographies and back. A camera sensor's mosaic and noise do not survive the round trip the way a generator's output does. Each tile's **fragility**, how much more of it the stronger warp loses, becomes four ordinal bits against its neighbours. The signature adds nothing to the pixels, and a crop or a re-encode is matched against it.\n\n| Subpackage | Holds |\n|---|---|\n| `VeilGardeCore` | the domain, with no MLX: the camera row, the XGBoost codec, heads and the combiner, bundles, the schema-v1 result, the feature store and its migration |\n| `VeilGardeLens` | the extractors: capture, DINOv2, CLIP, and the boosted-tree evaluator |\n| `VeilGardeInference` | the detector as one pipeline: the shared signals, the stack's members, the revisions, the result |\n| `VeilGardeTraining` | the trainers for the camera head, the heads and the combiner, declared as trainable members in a recipe DSL that mirrors the pipeline, and the backbone imports |\n| `VeilGardeFlywheel` | acquisition into a features-only store, candidates, the battery, promote and rollback |\n| `VeilWatermark` | the warp residual and a crop-robust signature read off each tile's fragility |\n| `veilgarde` | the CLI over all of it |\n\n## Detection as a declaration\n\nThe detector is one Swift value. Its shape in the code is its architecture: what reads the image, in what order, and what decides.\n\n```swift\npublic static var v1: Pipeline {\n    Pipeline {\n        Stack {\n            Screenshot()\n            Camera()\n            Capture()\n            Specialist(.art)\n            Specialist(.blur)\n            Specialist(.human)\n            Specialist(.preview)\n            SemanticTiles()\n        }\n        Revisions {\n            Combine()\n            FrameSeam()\n            PreviewTail()\n        }\n    }\n}\n```\n\nAn image moves through five stages:\n\n1. **Decode** reads the file the one way every model was trained on.\n2. **Shared Signals** computes what every member reads, once: the screenshot gate, the capture measurement, two DINOv2 readings and the patch tokens.\n3. **Stack** asks every member for its own take. A member reads only the shared signals, never another member, and reports its own P(AI), its verdict and what it measured.\n4. **Revisions** read the stack in order. The combiner sets the verdict around one anchor; the frame seam and the preview tail change it only on decisive evidence.\n5. **Result** keeps the verdict beside every member's score and every revision's record, as schema-v1 JSON.\n\nTraining is declared the same way. The recipe lists the trainable members, and the engine trains each in dependency order without knowing any by name:\n\n```swift\nTrainingRecipe(id: \"weekly\") {\n    CameraHead().warmStart(add: 80, eta: 0.03)\n    for kind in HeadKind.flywheelCategories { SpecialistHead(kind) }\n    Combiner()\n}\n```\n\nThat symmetry is what makes the engine iterative. A new detector for a new kind of generated image is a new member:\n\n1. one file that conforms to `StackMember`, a name and `score(_:)` from the shared signals to its own output, and one line in the `Stack`;\n2. if it learns from data, one file that conforms to `TrainableMember` and one line in the recipe;\n3. if the verdict should weigh it, its name in the combiner's file, which a refit writes.\n\nNothing else changes. The new member's score appears in every result from its first run, so it is measured on its own and inside the verdict before anyone decides to trust it. The flywheel then grows it like the others: it finds where the stack is wrong, fetches images of that kind, keeps only their features, trains candidates and promotes one only behind the battery.\n\nDINOv2 and the capture measurement run on the GPU through MLX, by way of [Frigate](https://github.com/rao-studios/Frigate); every trainer runs on the CPU from stored features, so a retrain never touches an image. The pipeline took this shape on 2026-10-21, and no verdict or score moved in the change.\n\n## Detection accuracy\n\n> **Work in progress.** The dataset, the training regime and the golden anchors are being revised, with the aim of raising accuracy on generated images to 80% in the coming weeks. The numbers below are v1's, measured on 2026-10-21, and will change as that work lands.\n\n**v1** is the shipped detector: the camera head over DINOv2 and the capture signature, and the specialist members, pooled by the combiner. Its battery, `battery_spec.json` version 1, passes on 96 images and is the baseline for testing; four generated images it misses are set aside for research. Measured on 2026-10-21. The same day the stack became a list of members, and no number moved: the census calls before and after are identical. A real image counts as right when it's called real; a generated image when it's called generated. \"Inconclusive\" counts as wrong.\n\n| Detector | Real, final_mixed census | Generated, final_mixed census | Real, unseen final_mixed | Generated, unseen final_mixed | Real, iPhone originals |\n|---|---|---|---|---|---|\n| **v1**, shipped: camera head + stack | 95% | 41% | 90.0% | 34.5% | 99.3% |\n| Residual head, in-sample combiner | 97% | 91% | 85.3% | 56.6% | 99.8% |\n| Residual head, out-of-fold combiner | 97% | 89% | 87.6% | 52.0% | 99.8% |\n| The warp era, for reference | 91% | 70% | not measured | not measured | 99.8% |\n\n- **Census:** 100 real and 100 generated final_mixed images. Most of them are rows the camera heads trained on, so these columns read high.\n- **Unseen:** the 3,217 final_mixed images in no store shard (1,602 real, 1,615 generated). This is the honest measure.\n- **iPhone originals:** 438 camera photos, all real.\n- **Residual head:** both DINOv2 readings, capture and the warp residual's statistics, 815 columns, 1,000 trees of depth 7. It did not ship, and its code left on 2026-10-21; its rows are the record.\n\n## The CLI at a glance\n\n```sh\nscripts/cli.sh doctor                                   # builds veilgarde, installs MLX's Metal library, checks the setup\nscripts/cli.sh route photo.jpg                          # the full detector: the verdict, every member's score, every revision\nscripts/cli.sh route photo.jpg --json                   # the same, as the schema-v1 result\nscripts/cli.sh train plan --preset                      # what the shipped recipe would train, without training\nVEILGARDE_CONFIG=release scripts/cli.sh train heads     # a candidate bundle under <work area>/candidates/\nscripts/cli.sh flywheel init && scripts/cli.sh flywheel battery --gate full\nVEILGARDE_CONFIG=release scripts/cli.sh research census  # every call of a bundle on the battery and 200 labelled images\nscripts/cli.sh watermark sign photo.jpg > photo.vw1 && scripts/cli.sh watermark match crop.jpg photo.vw1\n```\n\n`scripts/cli.sh` builds `veilgarde`, installs `mlx.metallib` beside it, and finds Frigate. `scripts/cli.sh <command> --help` lists a command's flags.\n\n## The playground\n\n[Playground/](Playground/README.md) runs both regimes on this Mac in one program and exits 0 only when every checkpoint holds: one image's capture signature and DINOv2 embeddings, the camera head's row built by hand, every member of the stack and the combiner revision's arithmetic term by term, then each trainer in miniature, the flywheel's promote and rollback, and the watermark. [The site's chapter 9](docs/site/09-playground.html) walks through it.\n\n```sh\nPlayground/run.sh\n```\n\n## VeilGarde docsite\n\nA site that explains each layer and shows every file this build changed, verbatim, with each Swift declaration's calls and callers, and the run's ledger of commands, tests and decisions. Nine trails walk the code in the order it runs: how the camera head and the specialist stack are trained, detection stage by stage from Decode through Shared Signals, Stack and Revisions to Result, and how the watermark signs an image and matches a crop of it. A grid picks them, a row for each flow and a column for each kind. Double-click scripts/site.command, or open [docs/site/index.html](docs/site/index.html); it is plain HTML with no build step. [docs/site/README.md](docs/site/README.md) says how it is rebuilt and checked.\n\nThe site's chat asks Mistral about what you are reading. On a Mac that holds a Mistral key in its key store, `scripts/site.command` hands the site that key; anyone else is asked for their own key in a dialog when the chat opens, and it stays in their browser.\n\n## Requirements and tests\n\n- Xcode 27 (Swift 6.4), macOS 26, Apple silicon.\n- [Frigate](https://github.com/rao-studios/Frigate), the family's MLX stack, checked out beside this repo or named by `VEILGARDE_FRIGATE_DIR`.\n- A work area, the folder `VEILGARDE_WORK_AREA` (or `--work-area`) names: the live bundle, the weights, the feature store, candidates and the battery. VeilGarde writes nowhere else. Datasets live under `VEILGARDE_DATASETS`, else the work area's `datasets/`.\n- The weights, in the work area's `weights/`: `veilgarde weights import-dinov2` builds DINOv2's from Hugging Face's checkpoint, and `veilgarde weights import-clip` CLIP's vision tower for acquisition.\n- Tests: `swift build --build-tests`, then `./build-metallib.sh debug` to put MLX's Metal library into the test bundles, then `VEILGARDE_MLX_TESTS=1 swift test --skip-build --no-parallel` (without `VEILGARDE_MLX_TESTS`, only the CPU suites run). Before the next test build, delete the `mlx.metallib` copies inside `.build`'s `.xctest` bundles: a bundle that holds one fails to re-sign.\n\nInside each target, folders follow the order of operations. The site's chapters walk them, and its change explorer shows every file.\n\n## Where it came from\n\nVeilGarde consolidates the detector's research into one tool. It was ported from Garde on 2026-10-19, ([CLR](https://rao.nyc/thoughts/2026-04-25), [CLR (Journey)](https://paka.la/blog/clr-journey)), the R&D it supersedes, and its trainers reproduce the research's Python recipes, whose numbers it quotes with their dates. On 2026-10-21 it was cut to its two lanes: the warp model, its calibration, the noiseprint and the reduction studies left the detector, and the code before the cut lives on the `2026-rnd` branch. The same day the detector became a stack of independent members with one DSL on both sides, and the goldens, the battery and the census did not move. It takes MLX from Frigate, and its layout, recipes, docs site and explorer from Braid.\n\nGNU General Public License v3.0 (see [LICENSE](LICENSE)).\n"},{"path":"build-metallib.sh","status":"added","lang":"shell","hunks":[[1,0,1,34]],"header":{"lines":[2,12],"style":"hash","what":[3,3],"pin":[6,11],"in":[4,4],"out":[5,5]},"marks":[],"first":1600,"scopes":[],"old":"","new":"#!/usr/bin/env bash\n# SPDX-License-Identifier: GPL-3.0-only\n# WHAT: Build MLX's mlx.metallib into this package's .build.\n# IN:   [debug|release] (default debug). VEILGARDE_FRIGATE_DIR overrides where Frigate lives.\n# OUT:  mlx.metallib beside every VeilGarde binary and inside every .xctest bundle.\n# PIN:  A delegate, not an implementation. Frigate owns the vendored .metal sources, so it owns the\n#       compile; `swift build` has no Metal step, and without this script the first GPU op dies\n#       with \"Failed to load the default metallib\". Run it after `swift build` (or\n#       `swift build --build-tests`), because it installs into the existing .build tree.\n#\n#   ./build-metallib.sh [debug|release]\n#\nset -euo pipefail\n\nREPO_ROOT=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n# Frigate, the vendored MLX stack, is taken by path: VEILGARDE_FRIGATE_DIR, else a checkout beside this repo\n# (https://github.com/rao-studios/Frigate). A machine's own settings, kept in a gitignored scripts/lib.sh, come first.\n[ -f \"$REPO_ROOT/scripts/lib.sh\" ] && source \"$REPO_ROOT/scripts/lib.sh\"\nVEILGARDE_FRIGATE_DIR=\"${VEILGARDE_FRIGATE_DIR:-$REPO_ROOT/../Frigate}\"\nif [ ! -f \"$VEILGARDE_FRIGATE_DIR/Package.swift\" ]; then\n    echo \"veilgarde: no Frigate at $VEILGARDE_FRIGATE_DIR: check it out beside this repo, or set VEILGARDE_FRIGATE_DIR\" >&2\n    exit 69\nfi\nexport VEILGARDE_FRIGATE_DIR=\"$(cd \"$VEILGARDE_FRIGATE_DIR\" && pwd)\"\nexport GIT_LFS_SKIP_SMUDGE=1    # Frigate's LFS fixtures break SwiftPM checkouts otherwise\nCANONICAL=\"$VEILGARDE_FRIGATE_DIR/scripts/build-metallib.sh\"\n\nif [ ! -x \"$CANONICAL\" ]; then\n    echo \"build-metallib: cannot find $CANONICAL\" >&2\n    echo \"  Set VEILGARDE_FRIGATE_DIR to your Frigate checkout.\" >&2\n    exit 1\nfi\n\nexec \"$CANONICAL\" \"${1:-debug}\" --package \"$REPO_ROOT\"\n"}]};
